.psps-map .maplibregl-ctrl-group button+button{border-top:0}
.psps-map .maplibregl-ctrl-group button:last-child{border-bottom:0}
.psps-map .maplibregl-ctrl-group button:hover{background-color:var(--paper)}
.psps-map .maplibregl-ctrl-group button:active{background:var(--paper-2)}
.psps-map .maplibregl-ctrl-group button:focus-visible{outline:2px solid var(--red);outline-offset:-4px}
.psps-map .maplibregl-ctrl-group button .maplibregl-ctrl-icon{display:none}
.psps-loc button{font-size:20px!important;color:var(--red)!important}
.psps-map .maplibregl-ctrl-attrib{background:rgba(243,234,217,.92)!important;color:#251a15;font:10px/1.3 Arial,sans-serif;border-radius:4px;direction:ltr}
.psps-map .maplibregl-ctrl-attrib a{color:#251a15;text-decoration:underline}
.psps-map .maplibregl-ctrl-attrib-button{background-color:transparent}
.psps-map .maplibregl-ctrl-bottom-right{right:0;bottom:0}
.map-tile-status{position:absolute;z-index:1000;bottom:30px;left:12px;right:12px;background:var(--paper);border:2px solid var(--ink);border-radius:9px;padding:9px 10px;font-size:11px;color:#5f392d;text-align:center;box-shadow:2px 3px 0 var(--ink)}
.map-tile-status[hidden]{display:none}
.psps-map .maplibregl-marker{will-change:transform}
.map-pin{position:absolute;left:0;top:0;width:0;height:0;transform:none;pointer-events:none}
.map-pin .marker{position:absolute;left:-23px;top:-56px;width:46px;height:46px;padding:0;margin:0;border:3px solid var(--ink);border-radius:50% 50% 50% 0;transform:rotate(-45deg);display:grid;place-items:center;background:var(--red);box-shadow:2px 3px 0 var(--ink);pointer-events:auto;cursor:pointer;z-index:2;-webkit-appearance:none;appearance:none}
.map-pin .marker:hover,.map-pin .marker:focus-visible{scale:1;filter:brightness(1.07)}
.map-pin .marker .marker-face{display:block;width:32px;height:32px;border:0;border-radius:50%;overflow:hidden;transform:rotate(45deg);background:var(--paper)}
.map-pin .marker .marker-face img,.map-pin .marker .marker-face .doodle-cat{width:100%;height:100%;display:block;object-fit:cover}
.map-pin .marker-label{position:absolute;left:0;top:6px;transform:translateX(-50%);white-space:nowrap;pointer-events:none;font-size:10px;line-height:1.7;font-weight:800;color:var(--ink);background:var(--paper);border:2px solid var(--ink);border-radius:6px;padding:0 6px;box-shadow:2px 2px 0 var(--ink);max-width:150px;overflow:hidden;text-overflow:ellipsis}
.location-picker-wrap{border:2px solid var(--ink);border-radius:12px;margin:0 0 15px;overflow:hidden}
.location-picker-head{padding:10px 13px;display:flex;justify-content:space-between;align-items:center;gap:10px}
.location-picker-head strong{font-size:11px}.location-picker-head small{font-size:9px;color:#665143}
.picker-map{height:240px;border-top:2px solid var(--ink)}
.map-wrap .map-caption{border-top:2px solid var(--ink)}
.map-caption{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
button.location-chip{font:inherit;text-align:right;cursor:pointer;color:inherit}
button.location-chip:active{transform:translate(2px,3px);box-shadow:1px 1px 0 var(--ink)}
.download-map:disabled{opacity:.7;cursor:progress}
.map-caption .text-btn{margin-right:0}
.g{width:22px;height:22px;flex:none;display:block}
/* user location: cat pin */
.me-cat{position:absolute;left:0;top:0;width:0;height:0;pointer-events:none}
.me-cat .me-pin{position:absolute;left:-24px;top:-58px;width:48px;height:58px;filter:drop-shadow(2px 3px 0 var(--ink));animation:meBob 2.4s ease-in-out infinite;transform-origin:50% 100%}
.me-cat .me-pin svg{width:100%;height:100%;display:block;overflow:visible}
.me-cat .me-ring{position:absolute;left:-16px;top:-6px;width:32px;height:12px;border:2px solid var(--red);border-radius:50%;opacity:0;animation:meRing 2.4s ease-out infinite}
.me-cat .me-tag{position:absolute;left:0;top:6px;transform:translateX(-50%);white-space:nowrap;font:800 10px/1.7 inherit;color:var(--paper);background:var(--ink);border-radius:6px;padding:0 7px}
@keyframes meBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
@keyframes meRing{0%{transform:scale(.4);opacity:.9}100%{transform:scale(2.2);opacity:0}}
/* stepper */
.stepper.gfx{display:flex!important;align-items:flex-start;justify-content:space-between;gap:0!important;margin:6px 0 16px;position:relative;font-size:11px!important}
.stepper.gfx span{flex:none;display:flex;flex-direction:column;align-items:center;gap:5px;width:84px;color:var(--muted);font-weight:800;z-index:1;text-align:center}
.stepper.gfx span b{width:44px;height:44px;border:2px solid var(--ink);border-radius:14px;background:var(--paper);display:grid;place-items:center;box-shadow:2px 3px 0 var(--ink);transition:.25s;color:var(--ink)}
.stepper.gfx span.active b{background:var(--ink);color:var(--paper)}
.stepper.gfx span.cur b{background:var(--red);color:var(--paper);transform:translateY(-2px) rotate(-4deg)}
.stepper.gfx span.cur{color:var(--red)}
.stepper.gfx span em{font-style:normal;line-height:1.5}
.stepper.gfx i{flex:1;height:0;border-top:3px dashed var(--line-soft);margin-top:21px;background:none!important;transition:.25s}
.stepper.gfx i.on{border-top:3px solid var(--ink)}
/* condition tiles */
.mini-q{display:block;font-weight:900;margin:12px 0 7px}
.cond-tiles{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}
.cond-tiles label{position:relative;display:flex!important;flex-direction:column;align-items:center;gap:4px;padding:8px 3px 7px;border:2px solid var(--ink);border-radius:12px;background:var(--paper);cursor:pointer;font-size:10px;font-weight:800;line-height:1.45;text-align:center;box-shadow:2px 3px 0 var(--ink);transition:.15s}
.cond-tiles input{position:absolute;opacity:0;inset:0;width:100%;height:100%;margin:0;cursor:pointer}
.cond-tiles .g{width:34px;height:34px}
.cond-tiles label:has(input:checked){background:var(--red);color:var(--paper);transform:translateY(-2px)}
.cond-tiles label:has(input:focus-visible){outline:3px solid var(--ink);outline-offset:2px}
/* switches */
.switch{display:flex!important;flex-direction:row!important;align-items:center;gap:11px;padding:10px 12px;border:2px solid var(--ink);border-radius:12px;background:var(--paper);box-shadow:2px 3px 0 var(--ink);cursor:pointer;position:relative;margin:12px 0;font-weight:800}
.switch input{position:absolute;opacity:0;inset:0;width:100%!important;height:100%!important;margin:0;cursor:pointer}
.switch .sw-ico{width:38px;height:38px;border:2px solid var(--ink);border-radius:11px;display:grid;place-items:center;background:var(--paper-2);flex:none;transition:.2s}
.switch .sw-ico .g{width:22px;height:22px}
.switch .sw-txt{display:flex;flex-direction:column;gap:1px;font-size:12px}
.switch .sw-txt small{font-weight:500;color:var(--muted);font-size:10px}
.switch .sw{margin-inline-start:auto;width:46px;height:26px;border:2px solid var(--ink);border-radius:99px;background:var(--paper-2);position:relative;flex:none;transition:.2s}
.switch .sw:after{content:"";position:absolute;top:2px;inset-inline-start:2px;width:18px;height:18px;border-radius:50%;background:var(--ink);transition:.2s}
.switch:has(input:checked) .sw{background:var(--red)}
.switch:has(input:checked) .sw:after{inset-inline-start:22px;background:var(--paper)}
.switch:has(input:checked) .sw-ico{background:var(--red);color:var(--paper);animation:wiggle .5s}
.switch.ok:has(input:checked) .sw,.switch.ok:has(input:checked) .sw-ico{background:var(--ink)}
.switch:has(input:focus-visible){outline:3px solid var(--ink);outline-offset:2px}
@keyframes wiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(-12deg)}75%{transform:rotate(12deg)}}
/* need tiles */
.need-options.tiles{display:grid!important;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:9px;margin:8px 0 12px}
.need-options.tiles>label.nt{position:relative;display:flex!important;flex-direction:column;align-items:center;gap:6px;padding:12px 6px 9px;border:2px solid var(--ink)!important;border-radius:14px!important;background:var(--paper);cursor:pointer;font-size:11px!important;font-weight:800;text-align:center;box-shadow:2px 3px 0 var(--ink);transition:.15s;margin:0}
.nt input{position:absolute;opacity:0;inset:0;width:100%!important;height:100%!important;margin:0;cursor:pointer}
.nt .nt-ico{width:46px;height:46px;border-radius:50%;border:2px solid var(--ink);display:grid;place-items:center;background:var(--paper-2);transition:.2s}
.nt .nt-ico .g{width:26px;height:26px}
.nt .nt-chk{position:absolute;top:-7px;inset-inline-end:-7px;width:22px;height:22px;border-radius:50%;background:var(--ink);color:var(--paper);display:grid;place-items:center;transform:scale(0);transition:.2s}
.nt .nt-chk .g{width:13px;height:13px;stroke-width:3.2}
.nt:has(input:checked){background:var(--red-soft)}
.nt:has(input:checked) .nt-ico{background:var(--red);color:var(--paper);transform:scale(1.08) rotate(-5deg)}
.nt:has(input:checked) .nt-chk{transform:scale(1)}
.nt:has(input:focus-visible){outline:3px solid var(--ink);outline-offset:2px}
.is-resolved .need-options.tiles,.is-resolved .need-lab,.is-resolved #updatedNeedText{opacity:.35;pointer-events:none}
/* quick chips */
.quick{display:flex;flex-wrap:wrap;gap:7px;margin:4px 0 8px}
.quick button{display:inline-flex;align-items:center;gap:6px;padding:6px 11px 6px 9px;border:2px solid var(--ink);border-radius:99px;background:var(--paper);font:800 11px inherit;cursor:pointer;box-shadow:1px 2px 0 var(--ink);color:var(--ink)}
.quick button .g{width:16px;height:16px}
.quick button:active,.quick button.on{background:var(--ink);color:var(--paper)}
/* upload */
.upload{border:2px dashed var(--ink)!important;border-radius:16px!important;background:var(--paper) repeating-linear-gradient(135deg,var(--paper) 0 10px,var(--paper-2) 10px 20px)!important}
#uploadPrompt{display:flex;flex-direction:column;align-items:center;gap:6px}
#uploadPrompt svg{width:46px!important;height:46px!important;padding:11px;background:var(--red);color:var(--paper);border:2px solid var(--ink);border-radius:50%;box-shadow:2px 3px 0 var(--ink)}
/* detail */
.detail-cover{position:relative}
.journey{position:relative;display:flex;justify-content:space-between;margin:2px 0 18px;padding:0 2px}
.journey:before{content:"";position:absolute;top:22px;inset-inline:30px;border-top:3px dashed var(--line-soft)}
.journey .jfill{position:absolute;top:22px;inset-inline-start:30px;height:3px;background:var(--ink);width:calc((100% - 60px) * var(--p,0));transition:width .6s cubic-bezier(.3,1.3,.5,1)}
.journey .j{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:5px;width:70px;text-align:center;font-size:10px;font-weight:800;color:var(--muted)}
.journey .j b{width:44px;height:44px;border:2px solid var(--ink);border-radius:50%;background:var(--paper);display:grid;place-items:center;color:var(--muted);transition:.3s}
.journey .j.on{color:var(--ink)}
.journey .j.on b{background:var(--ink);color:var(--paper)}
.journey .j.cur b{background:var(--red);color:var(--paper);box-shadow:0 0 0 5px #f0342033,2px 3px 0 var(--ink);animation:pulse 1.8s infinite}
.journey .j.cur{color:var(--red)}
.journey.is-done .j.cur b{background:var(--ink);box-shadow:2px 3px 0 var(--ink);animation:none}
.journey.is-done .j.cur{color:var(--ink)}
@keyframes pulse{50%{box-shadow:0 0 0 9px #f0342010,2px 3px 0 var(--ink)}}
.stats{display:grid;grid-template-columns:1fr 1.5fr;gap:9px;margin-bottom:14px}
.stat{display:flex;align-items:center;gap:10px;padding:10px 11px;border:2px solid var(--ink);border-radius:12px;box-shadow:2px 3px 0 var(--ink);background:var(--paper);min-width:0}
.stat .g{width:26px;height:26px;color:var(--red)}
.stat div{min-width:0;display:flex;flex-direction:column;line-height:1.5}
.stat small{font-size:9px;color:var(--muted);font-weight:700}
.stat b{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.coords{margin:-4px 0 14px;font-size:10px;color:var(--muted)}
.coords summary{cursor:pointer;font-weight:800;list-style:none;display:inline-flex;gap:6px;align-items:center}
.coords summary::-webkit-details-marker{display:none}
.mood{display:flex;gap:7px;margin:6px 0 8px}
.mood span{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;padding:7px 2px;border:2px solid var(--line-soft);border-radius:12px;color:var(--line-soft);font-size:9px;font-weight:800;text-align:center;line-height:1.4;transition:.2s}
.mood span .g{width:30px;height:30px}
.mood span.on{border-color:var(--ink);background:var(--red);color:var(--paper);box-shadow:2px 3px 0 var(--ink);transform:translateY(-3px) scale(1.04)}
.mood span:not(.on) em{visibility:hidden}
.mood em{font-style:normal}
.bubble{position:relative;border:2px solid var(--ink);border-radius:16px 16px 16px 4px;padding:11px 14px;background:var(--paper-3);margin:12px 0 16px;font-size:12px;line-height:2;color:var(--ink-2)}
.sec-t{display:flex;align-items:center;gap:8px;margin:18px 0 9px;font-size:13px;font-weight:900}
.sec-t .g{width:20px;height:20px;color:var(--red)}
.need-big{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:9px}
.need-big>div{display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px 6px 9px;border:2px solid var(--ink);border-radius:14px;background:var(--red-soft);box-shadow:2px 3px 0 var(--ink);font-size:11px;font-weight:800;text-align:center;animation:pop .45s both;animation-delay:calc(var(--i)*70ms)}
.need-big .ni{width:46px;height:46px;border-radius:50%;border:2px solid var(--ink);display:grid;place-items:center;background:var(--red);color:var(--paper)}
.need-big .ni .g{width:26px;height:26px}
@keyframes pop{from{transform:scale(.6);opacity:0}}
.all-good{display:flex;align-items:center;gap:12px;padding:12px;border:2px solid var(--ink);border-radius:14px;background:var(--paper-2);box-shadow:2px 3px 0 var(--ink);font-weight:800;font-size:12px}
.all-good .ni{width:46px;height:46px;border-radius:50%;border:2px solid var(--ink);display:grid;place-items:center;background:var(--ink);color:var(--paper);flex:none}
.given-card{display:flex;gap:11px;align-items:flex-start;padding:11px 12px;border:2px solid var(--ink);border-radius:14px;background:var(--paper);box-shadow:2px 3px 0 var(--ink);margin-top:11px}
.given-card .ni{width:38px;height:38px;border-radius:11px;border:2px solid var(--ink);display:grid;place-items:center;background:var(--ink);color:var(--paper);flex:none}
.given-card small{font-size:9px;font-weight:800;color:var(--muted)}
.given-card p{margin:1px 0 0;font-size:11.5px;line-height:1.9}
.going-banner{display:flex;align-items:center;gap:10px;padding:10px 12px;margin:14px 0 0;border:2px solid var(--ink);border-radius:14px;background:var(--paper-2);box-shadow:2px 3px 0 var(--ink);font-weight:800;font-size:12px}
.going-banner .g{width:28px;height:28px;animation:walk 1s ease-in-out infinite alternate}
@keyframes walk{to{transform:translateX(-6px) rotate(-6deg)}}
.detail-actions .primary,.detail-actions .secondary{min-height:50px;font-size:13px!important}
.detail-actions .primary:not(:disabled):active{transform:translate(2px,3px);box-shadow:none}
.tl{position:relative;margin:4px 0 6px;padding-inline-start:0}
.tl-i{position:relative;display:flex;gap:11px;padding-bottom:14px}
.tl-i:not(:last-child):before{content:"";position:absolute;top:36px;bottom:0;inset-inline-start:17px;border-inline-start:3px dotted var(--line-soft)}
.tl-i .ti{width:36px;height:36px;border-radius:50%;border:2px solid var(--ink);display:grid;place-items:center;background:var(--paper);flex:none;z-index:1}
.tl-i .ti .g{width:18px;height:18px}
.tl-i.first .ti{background:var(--ink);color:var(--paper)}
.tl-i.ok .ti{background:var(--ink);color:var(--paper)}
.tl-i.go .ti{background:var(--red);color:var(--paper)}
.tl-i b{font-size:12px}
.tl-i small{display:block;font-size:9px;color:var(--muted);font-weight:700}
.tl-i p{margin:2px 0 0;font-size:11px;line-height:1.8;color:var(--ink-2)}
.update-box.gfx{padding:16px!important}
.ub-head{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.ub-head .ni{width:42px;height:42px;border-radius:12px;border:2px solid var(--ink);display:grid;place-items:center;background:var(--red);color:var(--paper);box-shadow:2px 3px 0 var(--ink);transform:rotate(-5deg)}
.ub-head h3{margin:0;font-size:14px}
.update-box.gfx textarea{min-height:58px}
.update-box.gfx .primary{width:100%;display:flex;justify-content:center;gap:8px;min-height:48px;margin-top:6px}
/* mini track on cards */
.mini-track{display:flex;gap:4px;margin:9px 0 2px}
.mini-track i{flex:1;height:6px;border-radius:9px;border:1.5px solid var(--ink);background:var(--paper)}
.mini-track i.on{background:var(--ink)}
.mini-track i.cur{background:var(--red)}
.mini-track.done i.cur{background:var(--ink)}
.need-tag.ic{display:inline-flex;align-items:center;gap:4px}
.need-tag.ic .g{width:13px;height:13px}
/* celebration */
.cele{position:fixed;inset:0;z-index:99999;display:grid;place-items:center;pointer-events:none;background:#17110f55;animation:fadeIn .2s}
.cele.out{opacity:0;transition:opacity .45s}
.cele-card{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;padding:22px 34px 18px;border:3px solid var(--ink);border-radius:22px;background:var(--paper);box-shadow:6px 7px 0 var(--ink);animation:bounceIn .55s cubic-bezier(.3,1.6,.5,1)}
.cele-card .cat{width:104px;height:124px;filter:drop-shadow(2px 3px 0 var(--ink))}
.cele-card b{font-size:17px;font-weight:900}
.cele-card small{font-size:11px;color:var(--muted);font-weight:700}
.cele .paw{position:absolute;left:50%;top:44%;width:22px;height:22px;color:var(--red);opacity:0;animation:fly 1.2s ease-out forwards;animation-delay:calc(var(--i)*40ms)}
.cele.done .paw{color:var(--ink)}
@keyframes fly{0%{opacity:1;transform:translate(0,0) scale(.5) rotate(0)}100%{opacity:0;transform:translate(var(--x),var(--y)) scale(1.3) rotate(var(--r))}}
@keyframes bounceIn{from{transform:scale(.4);opacity:0}}
@keyframes fadeIn{from{opacity:0}}
@media(max-width:520px){.cond-tiles{grid-template-columns:repeat(3,1fr)}.stats{grid-template-columns:1fr}.journey .j{width:58px;font-size:9px}.stepper.gfx span{width:70px}}
@media(prefers-reduced-motion:reduce){.me-pin,.me-ring,.journey .j.cur b,.going-banner .g,.need-big>div,.cele-card,.cele .paw{animation:none!important}}

