/* ===== hero: the PsPs cat ===== */
.hero{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(200px,42%);align-items:center;gap:20px 28px;padding:34px 40px!important;min-height:0!important;overflow:visible!important}
