/* stage keeps the illustration's own proportions so eyes & pin stay registered */
.hc{position:relative;display:block;width:min(100%,290px);aspect-ratio:440/452;padding:0;margin:0;border:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
.hc:focus-visible{outline:3px dashed var(--red);outline-offset:8px;border-radius:24px}
