.hc-eye{position:absolute;width:4.4%;aspect-ratio:1;margin:-2.2% 0 0 -2.2%;pointer-events:none}
.hc-eye.l{left:29.27%;top:56.57%}.hc-eye.r{left:44.27%;top:56.48%}
.hc-eye i{position:absolute;inset:0;border-radius:50%;background:var(--ink);transition:transform .18s var(--ease)}
