.hc-eye b i{transform-origin:50% 50%}
.hc.blink .hc-eye b i{transform:scaleY(.12)}
.hc.happy .hc-eye b i{background:none;border:0;border-top:3px solid var(--ink);border-radius:50% 50% 0 0;transform:translateY(25%) scale(1.5,1.1)}
.hc .hero-speech{display:block!important;position:absolute!important;left:20%!important;right:auto!important;top:3%!important;bottom:auto!important;padding:5px 14px 6px!important;border:2px solid transparent!important;border-radius:18px!important;background:var(--paper)!important;color:var(--ink)!important;font:400 22px/1.1 "Caveat Brush","Trebuchet MS",sans-serif!important;white-space:nowrap;transform-origin:100% 100%;transform:rotate(-5deg);animation:none;box-shadow:none!important;pointer-events:none;transition:transform .4s var(--spring)}
.hc .hero-speech.pop{animation:bubblePop .55s var(--spring)}
.hc:hover .hero-speech{transform:rotate(-2deg) scale(1.06)}
