html[data-theme=dark] .theme-btn .t-sun{transform:none;opacity:1}
.theme-btn:hover .t-moon,.theme-btn:hover .t-sun{animation:wiggle .6s ease-in-out}
.theme-fade,.theme-fade *{transition:background-color .35s ease,color .35s ease,border-color .35s ease,fill .35s,stroke .35s!important}
.top-actions{display:flex;align-items:center;gap:10px}
@media (max-width:760px){.topbar .theme-btn{width:42px;height:42px}.top-actions{gap:8px}}
html[data-theme=dark] .bottom-nav{background:rgba(26,25,22,.94)!important}
html[data-theme=dark] .detail-dialog::before{background:rgba(26,25,22,.8)!important}
html[data-theme=dark] .doodle-cat{mix-blend-mode:normal!important;filter:none!important}

